import { TextInput, type KeyboardTypeOptions, type TextInputProps } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import type { InputProps, InputType } from "@/components/nyc-tron/ui/components/html/types";

const KEYBOARD:Record<InputType,KeyboardTypeOptions>={
  text:"default",search:"web-search",email:"email-address",url:"url",
  tel:"phone-pad",number:"decimal-pad",password:"default",
};
const INPUT_MODE:Record<InputType,TextInputProps["inputMode"]>={
  text:"text",search:"search",email:"email",url:"url",tel:"tel",number:"decimal",password:"text",
};

/**
 * Single-line text field on both platforms: a real `<input>` on web (React
 * Native Web's TextInput) and the platform field on native. For a labelled
 * field with helper and error text use TextField; this is the bare control
 * Forge's semantic set exposes. At least 44pt tall.
 */
export function Input({type="text",id,className,...props}:InputProps) {
  return (
    <TextInput
      {...props}
      nativeID={id}
      keyboardType={props.keyboardType??KEYBOARD[type]}
      inputMode={props.inputMode??INPUT_MODE[type]}
      secureTextEntry={props.secureTextEntry??type==="password"}
      autoCapitalize={props.autoCapitalize??(type==="text"?"sentences":"none")}
      {...{className:joinClasses("min-h-11",className)}}
    />
  );
}

import { Linking, Text as RNText, View, type GestureResponderEvent, type Role } from "react-native";
import type {
  HeadingProps, LinkProps, SemanticBaseProps, SemanticBlockProps, SemanticTextProps,
} from "@/components/nyc-tron/ui/components/html/types";

export { Input } from "@/components/nyc-tron/ui/components/html/Input";
export type {
  HeadingLevel, HeadingProps, InputProps, InputType, LinkProps,
  SemanticBaseProps, SemanticBlockProps, SemanticTextProps,
} from "@/components/nyc-tron/ui/components/html/types";

/**
 * Native fork: View and Text with the matching ARIA `role`, which RN 0.88
 * maps to the platform's accessibility traits where one exists (heading,
 * link, list). Landmarks have no iOS or Android equivalent, so `main`,
 * `banner`, `navigation` and the like are carried for parity and are silent
 * to VoiceOver and TalkBack. Roles go through `role`, never
 * `accessibilityRole`: Android's enum throws on values outside its list.
 */
function nativeProps({id,hidden,title:_title,dataSet:_dataSet,dir:_dir,lang:_lang,className,...rest}:SemanticBaseProps) {
  const props:Record<string,unknown>={};
  for(const [key,value] of Object.entries(rest)){
    if(!key.startsWith("data-"))props[key]=value;
  }
  return {
    ...props,
    nativeID:id,
    className,
    ...(hidden?{"aria-hidden":true,accessibilityElementsHidden:true,importantForAccessibility:"no-hide-descendants" as const}:{}),
  };
}
function block(role:Role|undefined,displayName:string) {
  const Block=({style,hidden,...props}:SemanticBlockProps)=>(
    <View {...nativeProps({hidden,...props})} role={role}
      style={hidden?[style,{display:"none"}]:style}/>
  );
  Block.displayName=displayName;
  return Block;
}

export const Page=block(undefined,"Page");
export const Main=block("main","Main");
export const Header=block("banner","Header");
export const Footer=block("contentinfo","Footer");
export const Section=block("region","Section");
export const Nav=block("navigation","Nav");
export const Article=block("article","Article");
export const Aside=block("complementary","Aside");

export function Text({style,hidden,...props}:SemanticTextProps) {
  return <RNText {...nativeProps({hidden,...props})} style={hidden?[style,{display:"none"}]:style}/>;
}
export function Paragraph(props:SemanticTextProps) {
  return <Text {...props}/>;
}
// RN Text has no heading level on iOS or Android; `aria-level` is carried for
// parity and only React Native Web announces it.
export function Heading({level=1,style,hidden,...props}:HeadingProps) {
  return <RNText {...nativeProps({hidden,...props})} role="heading"
    {...{"aria-level":level}} style={hidden?[style,{display:"none"}]:style}/>;
}

const EXTERNAL=/^(?:https?:|mailto:|tel:)/i;
export function Link({href,target:_target,rel:_rel,onPress,style,hidden,...props}:LinkProps) {
  const external=href!==undefined&&EXTERNAL.test(href);
  const press=onPress??(external?(_event:GestureResponderEvent)=>{Linking.openURL(href!).catch(()=>{});}:undefined);
  // A link that cannot go anywhere is plain text, never a dead control.
  return <RNText {...nativeProps({hidden,...props})} role={press?"link":undefined} onPress={press}
    style={hidden?[style,{display:"none"}]:style}/>;
}

import * as ReactNative from "react-native";
import { StyleSheet, type StyleProp } from "react-native";
import type { ReactElement } from "react";
import type {
  HeadingProps, LinkProps, SemanticBaseProps, SemanticBlockProps, SemanticTextProps,
} from "@/components/nyc-tron/ui/components/html/types";

export { Input } from "@/components/nyc-tron/ui/components/html/Input";
export type {
  HeadingLevel, HeadingProps, InputProps, InputType, LinkProps,
  SemanticBaseProps, SemanticBlockProps, SemanticTextProps,
} from "@/components/nyc-tron/ui/components/html/types";

/**
 * Web fork: real `<main>`, `<header>`, `<nav>`, `<h2>`, `<a>`… through React
 * Native Web's own element factory, the path RNW's View and Text use. Style
 * props, `dataSet`, aria props and RTL `dir` resolve exactly as on a View.
 *
 * View with a `role` would reach most of these elements too, but it always
 * writes the role attribute: a `<header role="banner">` nested in a section
 * would announce a second page banner. The factory emits the element with its
 * implicit role only.
 */
type Factory=(tag:string,props:object)=>ReactElement;
const createElement=(ReactNative as unknown as {unstable_createElement?:Factory}).unstable_createElement;
if(typeof createElement!=="function"){
  throw new Error("@nyc-tron/ui/components/html web build needs react-native-web (unstable_createElement).");
}

// RN View defaults, so block primitives lay out like the Views around them
// (flex column, no shrink); app classes override them as they do on a View.
const base=StyleSheet.create({
  block:{display:"flex",flexDirection:"column",alignItems:"stretch",flexBasis:"auto",flexShrink:0,
    minHeight:0,minWidth:0,position:"relative"},
  // UA margins, and link color/underline, are reset like RNW Text does; the
  // app's classes restyle them.
  text:{margin:0},
  link:{margin:0,color:"inherit",textDecorationLine:"none"},
});

function render(tag:string,{className,style,hidden,dataSet,children,...rest}:SemanticBaseProps&{style?:StyleProp<object>},
  baseStyle:object,extra?:object):ReactElement {
  const classes=className?{$$css:true,tw:className}:undefined;
  return createElement!(tag,{
    ...rest,...extra,dataSet,hidden,
    // `hidden` alone loses to a display utility; the inline style does not.
    style:[baseStyle,classes,style,hidden?{display:"none"}:undefined],
    children,
  });
}

export const Page=(props:SemanticBlockProps)=>render("div",props,base.block);
export const Main=(props:SemanticBlockProps)=>render("main",props,base.block);
export const Header=(props:SemanticBlockProps)=>render("header",props,base.block);
export const Footer=(props:SemanticBlockProps)=>render("footer",props,base.block);
export const Section=(props:SemanticBlockProps)=>render("section",props,base.block);
export const Nav=(props:SemanticBlockProps)=>render("nav",props,base.block);
export const Article=(props:SemanticBlockProps)=>render("article",props,base.block);
export const Aside=(props:SemanticBlockProps)=>render("aside",props,base.block);

// Text primitives inherit the app's font from the page instead of RNW Text's
// `14px System`, which a layered stylesheet cannot override. Like RNW Text
// they default to dir="auto", so punctuation in mixed-direction copy lands on
// the right side of each run.
const auto=<P extends {dir?:SemanticBaseProps["dir"]}>(props:P)=>({...props,dir:props.dir??"auto"});
export const Text=({numberOfLines:_n,selectable:_s,...props}:SemanticTextProps)=>render("span",auto(props),base.text);
export const Paragraph=({numberOfLines:_n,selectable:_s,...props}:SemanticTextProps)=>render("p",auto(props),base.text);
export function Heading({level=1,numberOfLines:_n,selectable:_s,...props}:HeadingProps) {
  return render("h"+level,auto(props),base.text);
}
export function Link({href,target,rel,onPress,numberOfLines:_n,selectable:_s,...props}:LinkProps) {
  return render("a",auto(props),base.link,{
    href,target,
    rel:target==="_blank"?joinRel(rel,"noopener noreferrer"):rel,
    onClick:onPress,
  });
}
const joinRel=(rel:string|undefined,add:string)=>[...new Set([...(rel??"").split(/\s+/),...add.split(" ")].filter(Boolean))].join(" ");

import type { ReactNode } from "react";
import type { GestureResponderEvent, StyleProp, TextInputProps, TextStyle, ViewStyle } from "react-native";

type DataAttributes={[attribute:`data-${string}`]:string|number|boolean|undefined};

/**
 * Props every semantic primitive takes on both platforms. The DOM-shaped
 * names (`id`, `hidden`, `title`, `data-*`) are what Nitro Forge's studio
 * preview passes; on native, `id` becomes `nativeID`, `hidden` removes the
 * subtree from layout and the accessibility tree, and `data-*` / `title` /
 * `dataSet` have no equivalent and are dropped.
 */
export type SemanticBaseProps=DataAttributes&{
  children?:ReactNode;
  className?:string;
  id?:string;
  hidden?:boolean;
  title?:string;
  dataSet?:Readonly<Record<string,string|number|boolean>>;
  testID?:string;
  dir?:"ltr"|"rtl"|"auto";
  lang?:string;
  "aria-label"?:string;
  "aria-labelledby"?:string;
  "aria-describedby"?:string;
  "aria-hidden"?:boolean;
};
export type SemanticBlockProps=SemanticBaseProps&{style?:StyleProp<ViewStyle>};
export type SemanticTextProps=SemanticBaseProps&{style?:StyleProp<TextStyle>;numberOfLines?:number;selectable?:boolean};
export type HeadingLevel=1|2|3|4|5|6;
export type HeadingProps=SemanticTextProps&{/** @default 1 */ level?:HeadingLevel};
export type LinkProps=SemanticTextProps&{
  href?:string;
  /** Web only. */
  target?:"_blank"|"_self"|"_parent"|"_top";
  /** Web only. `noopener noreferrer` is added for `_blank`. */
  rel?:string;
  /**
   * Runs before navigation. On native it replaces navigation: an app-router
   * path (`/editor/prism`, `#/apps/quill`) needs it, since only absolute
   * `http(s):`, `mailto:` and `tel:` hrefs open through `Linking`.
   */
  onPress?:(event:GestureResponderEvent)=>void;
};
export type InputType="text"|"search"|"email"|"url"|"tel"|"number"|"password";
export type InputProps=Omit<TextInputProps,"id">&{
  id?:string;
  /** Maps to the platform keyboard and secure entry; never a file input (use FilePicker). @default "text" */
  type?:InputType;
  className?:string;
  "aria-label"?:string;
};

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
